# Intent
  arrangeManager: discovery, slot auto-allocation, placement, reswing.

# Helpers
  @fn mkAm(harness, opts)  @ 7-12
  @fn seedTracks(h, specs)  @ 18-40
      -- Seed two arbitrary tracks and a per-track item list. Returns the
      -- track tokens so each test can name them. The harness's default
      -- bindTake(take1) is unrelated — we manage these via setProjectTracks
      -- so am sees them in CountTracks/GetTrack order.
  @fn slotFor(am, trackIdx, id)  @ 42-44
  @fn slotAt(am, trackIdx, slotIdx)  @ 46-48

# Cases
  @case 'projectTracks lists every track in REAPER order with item count'  [harness]  @ 55-71
  @case 'trackSlots auto-allocates slot indices for live takes'  [harness]  @ 78-92
  @case 'tracksTakes assigns slotIdx to every grouped take'  [harness]  @ 96-114
  @case 'ensureSlots is idempotent — second read does not reallocate'  [harness]  @ 118-129
  @case 'hasPlacedTakes ignores parked takes, sees placed instances'  [harness]  @ 133-142
  @case 'ownerTrack resolves a parked take to its logical track, not scratch'  [harness]  @ 149-163
  @case 'renameSlot writes SetTakeName across every matching item'  [harness]  @ 170-183
  @case 'renameSlot reroots the family, each slot keeping its own ordinal'  [harness]  @ 187-204
  @case 'renameSlot with a changed ordinal renames that slot alone'  [harness]  @ 208-218
  @case 'two slots holding the root plain are namesakes, not a family'  [harness]  @ 222-234
  @case 'with the root held plain twice, a variant reroots neither'  [harness]  @ 238-250
  @case 'an unnamed slot has no family'  [harness]  @ 254-264
  @case 'the reroot reaches a parked family member'  [harness]  @ 268-277
  @case 'renameSlot renames a parked slot through its keeper'  [harness]  @ 281-288
  @case 'deleteSlot removes every matching item and prunes the dict entry'  [harness]  @ 292-310
  @case 'pruneSlots forever-deletes every parked slot, MIDI and audio alike'  [harness]  @ 314-336
  @case 'tidySlots numbers a base\'s members plain then (var N), by ordinal then slot'  [harness]  @ 343-359
  @case 'a pinned slot holds its ordinal, and joins its base by name alone'  [harness]  @ 363-376
  @case 'two pinned members holding the base plain both keep it'  [harness]  @ 380-392
  @case 'an audio slot takes no part in a base'  [harness]  @ 396-408
  @case 'tidySlots writes every live instance and the parked keeper'  [harness]  @ 412-426
  @case 'createAndDropMidi mints slot 0, creates a take, names it'  [harness]  @ 433-449
  @case 'createAndDropMidi allocates lowest-free index across calls'  [harness]  @ 453-464
  @case 'dropInstance pools to an existing slot'  [harness]  @ 468-479
  @case 'dropInstance overwrites a take already starting at the drop position'  [harness]  @ 483-500
  @case 'createAndDropMidi overwrites a take already starting at the create position'  [harness]  @ 504-519
  @case 'dropInstance returns nil for missing slot or missing track'  [harness]  @ 523-529
  @case 'duplicateTake clones a MIDI take into a pooled sibling'  [harness]  @ 533-548
  @case 'dropInstance and duplicateTake name the new take after the slot'  [harness]  @ 552-563
  @case 'duplicateTake returns nil for a missing track'  [harness]  @ 567-575
  @case 'dropInstance carries the sibling MIDI events into the new instance'  [harness]  @ 579-589
  @case 'duplicateTake carries the source MIDI events into the clone'  [harness]  @ 593-604
  @case 'startIsClear only collides on an exact start match (item ~= exceptItem)'  [harness]  @ 608-623
  @case 'createAndDropMidi returns nil when no track exists'  [harness]  @ 627-632
  @case 'keyForSlot maps 0..61 through util.toBase62'  [harness]  @ 639-648
  @case 'takesUsing scans each take swing map (ds) for the named swing'  [harness]  @ 655-673
  @case 'tempersInUse unions take/project temper names, minus the 12EDO floor'  [harness]  @ 676-690
  @case 'tracksTakes relayouts on read: an OPEN take grows to its source length'  [harness]  @ 700-709
  @case 'build relayout: OPEN takes fill to source; an earlier one capped at its gap (no overlap)'  [harness]  @ 712-723
  @case 'build relayout: an OPEN take whose item outruns its shrunk source is pulled back'  [harness]  @ 726-734
  @case 'a later take truncates an earlier one; deleting the later regrows it'  [harness]  @ 738-752
  @case 'resizeTake stores a numeric natural; ≥ source demotes back to util.OPEN'  [harness]  @ 756-772
  @case 'audio take longer than its source keeps its length across a move'  [harness]  @ 775-790
  @case 'trimmed audio take keeps its trim across a move (no balloon to source)'  [harness]  @ 793-805
  @case 'moveTake shifts start; refused on start-collision; returns ok flag'  [harness]  @ 809-820
  @case 'resizeTake writes natural; rendered is min(natural, source, gap)'  [harness]  @ 824-835
  @case 'trimHead walks the start edge in, holding the content and the end still'  [harness]  @ 839-855
  @case 'a head is refused before the origin, at the source end, or onto an occupied start'  [harness]  @ 858-869
  @case 'tailQN is the source past the rendered end, whatever shortened the take'  [harness]  @ 872-881
  @case 'head, rendered length and tail partition the source'  [harness]  @ 884-896
  @case 'a trimmed take is capped by the gap, and regrows to source-minus-head without one'  [harness]  @ 899-912
  @case 'trimming the head of a resized take keeps the end where the resize put it'  [harness]  @ 915-926
  @case 'splitTake cuts a take into two pooled halves that meet at the cut'  [harness]  @ 932-949
  @case 'the lower half inherits the natural, so the pair ends where the whole did'  [harness]  @ 952-964
  @case 'splitting a head-trimmed take leaves both halves on the source origin'  [harness]  @ 967-981
  @case 'a split is refused on either edge, off the take, and on audio'  [harness]  @ 984-997
  @case 'deleteTake removes the item, leaving the other take intact'  [harness]  @ 1001-1012
  @case 'deleteTake parks a slot\'s last instance; the slot survives, greyed'  [harness]  @ 1018-1034
  @case 'deleteTake of a non-last instance deletes outright (no park)'  [harness]  @ 1038-1053
  @case 're-dropping from a parked slot re-materialises off the keeper'  [harness]  @ 1057-1070
  @case 'deleteSlot forever-deletes: live instances and the parked keeper'  [harness]  @ 1074-1087
  @case 'deleteSlot forever-deletes the pool per-event metadata'  [harness]  @ 1091-1102
