  @case 'vary replaces the instance with one of a fresh variant slot'  [harness]  @ 1128-1150
  @case 'vary numbers from the family high-water mark; a variant of a variant joins the family'  [harness]  @ 1154-1165
  @case 'vary refuses on a slot with a single instance'  [harness]  @ 1169-1177
  @case 'stepVariant moves the placement onto the next slot of the family'  [harness]  @ 1184-1203
  @case 'stepVariant past the last of the family varies'  [harness]  @ 1207-1220
